0001: static struct clock_source *dce110_clock_source_create(
0002: 	struct dc_context *ctx,
0003: 	struct dc_bios *bios,
0004: 	enum clock_source_id id,
0005: 	const struct dce110_clk_src_regs *regs,
0006: 	bool dp_clk_src)
0007: {
0008: 	struct dce110_clk_src *clk_src =
0009: 		kzalloc_obj(struct dce110_clk_src);
0010: 
0011: 	if (!clk_src)
0012: 		return NULL;
0013: 
0014: 	if (dce110_clk_src_construct(clk_src, ctx, bios, id,
0015: 			regs, &cs_shift, &cs_mask)) {
0016: 		clk_src->base.dp_clk_src = dp_clk_src;
0017: 		return &clk_src->base;
0018: 	}
0019: 
0020: 	kfree(clk_src);
0021: 	BREAK_TO_DEBUGGER();
0022: 	return NULL;
0023: }

0001: static inline u8 bnx2x_vlan_mac_get_rx_tx_flag(struct bnx2x_vlan_mac_obj *o)
0002: {
0003: 	struct bnx2x_raw_obj *raw = &o->raw;
0004: 	u8 rx_tx_flag = 0;
0005: 
0006: 	if ((raw->obj_type == BNX2X_OBJ_TYPE_TX) ||
0007: 	    (raw->obj_type == BNX2X_OBJ_TYPE_RX_TX))
0008: 		rx_tx_flag |= ETH_CLASSIFY_CMD_HEADER_TX_CMD;
0009: 
0010: 	if ((raw->obj_type == BNX2X_OBJ_TYPE_RX) ||
0011: 	    (raw->obj_type == BNX2X_OBJ_TYPE_RX_TX))
0012: 		rx_tx_flag |= ETH_CLASSIFY_CMD_HEADER_RX_CMD;
0013: 
0014: 	return rx_tx_flag;
0015: }

0001: static void uhci_release_bandwidth(struct uhci_hcd *uhci, struct uhci_qh *qh)
0002: {
0003: 	int i;
0004: 	int load = qh->load;
0005: 	char *p = "??";
0006: 
0007: 	for (i = qh->phase; i < MAX_PHASE; i += qh->period) {
0008: 		uhci->load[i] -= load;
0009: 		uhci->total_load -= load;
0010: 	}
0011: 	uhci_to_hcd(uhci)->self.bandwidth_allocated =
0012: 			uhci->total_load / MAX_PHASE;
0013: 	switch (qh->type) {
0014: 	case USB_ENDPOINT_XFER_INT:
0015: 		--uhci_to_hcd(uhci)->self.bandwidth_int_reqs;
0016: 		p = "INT";
0017: 		break;
0018: 	case USB_ENDPOINT_XFER_ISOC:
0019: 		--uhci_to_hcd(uhci)->self.bandwidth_isoc_reqs;
0020: 		p = "ISO";
0021: 		break;
0022: 	}
0023: 	qh->bandwidth_reserved = 0;
0024: 	dev_dbg(uhci_dev(uhci),
0025: 			"%s dev %d ep%02x-%s, period %d, phase %d, %d us\n",
0026: 			"release", qh->udev->devnum,
0027: 			qh->hep->desc.bEndpointAddress, p,
0028: 			qh->period, qh->phase, load);
0029: }

0001: static int csi2_link_setup(struct media_entity *entity,
0002: 			   const struct media_pad *local,
0003: 			   const struct media_pad *remote, u32 flags)
0004: {
0005: 	struct v4l2_subdev *sd = media_entity_to_v4l2_subdev(entity);
0006: 	struct isp_csi2_device *csi2 = v4l2_get_subdevdata(sd);
0007: 	struct isp_csi2_ctrl_cfg *ctrl = &csi2->ctrl;
0008: 	unsigned int index = local->index;
0009: 
0010: 	/*
0011: 	 * The ISP core doesn't support pipelines with multiple video outputs.
0012: 	 * Revisit this when it will be implemented, and return -EBUSY for now.
0013: 	 */
0014: 
0015: 	/* FIXME: this is actually a hack! */
0016: 	if (is_media_entity_v4l2_subdev(remote->entity))
0017: 		index |= 2 << 16;
0018: 
0019: 	switch (index) {
0020: 	case CSI2_PAD_SOURCE:
0021: 		if (flags & MEDIA_LNK_FL_ENABLED) {
0022: 			if (csi2->output & ~CSI2_OUTPUT_MEMORY)
0023: 				return -EBUSY;
0024: 			csi2->output |= CSI2_OUTPUT_MEMORY;
0025: 		} else {
0026: 			csi2->output &= ~CSI2_OUTPUT_MEMORY;
0027: 		}
0028: 		break;
0029: 
0030: 	case CSI2_PAD_SOURCE | 2 << 16:
0031: 		if (flags & MEDIA_LNK_FL_ENABLED) {
0032: 			if (csi2->output & ~CSI2_OUTPUT_CCDC)
0033: 				return -EBUSY;
0034: 			csi2->output |= CSI2_OUTPUT_CCDC;
0035: 		} else {
0036: 			csi2->output &= ~CSI2_OUTPUT_CCDC;
0037: 		}
0038: 		break;
0039: 
0040: 	default:
0041: 		/* Link from camera to CSI2 is fixed... */
0042: 		return -EINVAL;
0043: 	}
0044: 
0045: 	ctrl->vp_only_enable =
0046: 		(csi2->output & CSI2_OUTPUT_MEMORY) ? false : true;
0047: 	ctrl->vp_clk_enable = !!(csi2->output & CSI2_OUTPUT_CCDC);
0048: 
0049: 	return 0;
0050: }

0001: int nand_read_oob_op(struct nand_chip *chip, unsigned int page,
0002: 		     unsigned int offset_in_oob, void *buf, unsigned int len)
0003: {
0004: 	struct mtd_info *mtd = nand_to_mtd(chip);
0005: 
0006: 	if (len && !buf)
0007: 		return -EINVAL;
0008: 
0009: 	if (offset_in_oob + len > mtd->oobsize)
0010: 		return -EINVAL;
0011: 
0012: 	if (nand_has_exec_op(chip))
0013: 		return nand_read_page_op(chip, page,
0014: 					 mtd->writesize + offset_in_oob,
0015: 					 buf, len);
0016: 
0017: 	chip->legacy.cmdfunc(chip, NAND_CMD_READOOB, offset_in_oob, page);
0018: 	if (len)
0019: 		chip->legacy.read_buf(chip, buf, len);
0020: 
0021: 	return 0;
0022: }

0001: struct pmf_function *pmf_find_function(struct device_node *target,
0002: 				       const char *name)
0003: {
0004: 	struct pmf_function *func;
0005: 	unsigned long flags;
0006: 
0007: 	spin_lock_irqsave(&pmf_lock, flags);
0008: 	func = __pmf_find_function(target, name, PMF_FLAGS_ON_DEMAND);
0009: 	if (func)
0010: 		func = pmf_get_function(func);
0011: 	spin_unlock_irqrestore(&pmf_lock, flags);
0012: 	return func;
0013: }

0001: int perf_counter_info_read_values(struct perf_counter_info *pp, int cpu, unsigned long long *out, size_t out_size)
0002: {
0003: 	unsigned int domain;
0004: 	unsigned long long value;
0005: 	int fd_counter;
0006: 
0007: 	for (size_t i = 0; pp; ++i, pp = pp->next) {
0008: 		domain = cpu_to_domain(pp, cpu);
0009: 		assert(domain < pp->num_domains);
0010: 
0011: 		fd_counter = pp->fd_perf_per_domain[domain];
0012: 
0013: 		if (fd_counter == -1)
0014: 			continue;
0015: 
0016: 		if (read(fd_counter, &value, sizeof(value)) != sizeof(value))
0017: 			return 1;
0018: 
0019: 		assert(i < out_size);
0020: 		out[i] = value * pp->scale;
0021: 	}
0022: 
0023: 	return 0;
0024: }

