0001: static void falcon_remove_nic(struct ef4_nic *efx)
0002: {
0003: 	struct falcon_nic_data *nic_data = efx->nic_data;
0004: 	struct falcon_board *board = falcon_board(efx);
0005: 
0006: 	board->type->fini(efx);
0007: 
0008: 	/* Remove I2C adapter and clear it in preparation for a retry */
0009: 	i2c_del_adapter(&board->i2c_adap);
0010: 	memset(&board->i2c_adap, 0, sizeof(board->i2c_adap));
0011: 
0012: 	ef4_nic_free_buffer(efx, &efx->irq_status);
0013: 
0014: 	__falcon_reset_hw(efx, RESET_TYPE_ALL);
0015: 
0016: 	/* Release the second function after the reset */
0017: 	if (nic_data->pci_dev2) {
0018: 		pci_dev_put(nic_data->pci_dev2);
0019: 		nic_data->pci_dev2 = NULL;
0020: 	}
0021: 
0022: 	/* Tear down the private nic state */
0023: 	kfree(efx->nic_data);
0024: 	efx->nic_data = NULL;
0025: }

