0001: int __kprobes kprobe_fault_handler(struct pt_regs *regs, unsigned long trapnr)
0002: {
0003: 	struct kprobe *cur = kprobe_running();
0004: 	struct kprobe_ctlblk *kcb = get_kprobe_ctlblk();
0005: 
0006: 	switch (kcb->kprobe_status) {
0007: 	case KPROBE_HIT_SS:
0008: 	case KPROBE_REENTER:
0009: 		/*
0010: 		 * We are here because the instruction being single stepped
0011: 		 * caused the fault. We reset the current kprobe and allow the
0012: 		 * exception handler as if it is regular exception. In our
0013: 		 * case it doesn't matter because the system will be halted
0014: 		 */
0015: 		resume_execution(cur, (unsigned long)cur->addr, regs);
0016: 
0017: 		if (kcb->kprobe_status == KPROBE_REENTER)
0018: 			restore_previous_kprobe(kcb);
0019: 		else
0020: 			reset_current_kprobe();
0021: 
0022: 		preempt_enable_no_resched();
0023: 		break;
0024: 
0025: 	case KPROBE_HIT_ACTIVE:
0026: 	case KPROBE_HIT_SSDONE:
0027: 		/*
0028: 		 * We are here because the instructions in the pre/post handler
0029: 		 * caused the fault.
0030: 		 */
0031: 
0032: 		/*
0033: 		 * In case the user-specified fault handler returned zero,
0034: 		 * try to fix up.
0035: 		 */
0036: 		if (fixup_exception(regs))
0037: 			return 1;
0038: 
0039: 		/*
0040: 		 * fixup_exception() could not handle it,
0041: 		 * Let do_page_fault() fix it.
0042: 		 */
0043: 		break;
0044: 
0045: 	default:
0046: 		break;
0047: 	}
0048: 	return 0;
0049: }

0001: static void
0002: iwl_mld_resume_keys_iter(struct ieee80211_hw *hw,
0003: 			 struct ieee80211_vif *vif,
0004: 			 struct ieee80211_sta *sta,
0005: 			 struct ieee80211_key_conf *key,
0006: 			 void *_data)
0007: {
0008: 	struct iwl_mld_resume_key_iter_data *data = _data;
0009: 	struct iwl_mld_wowlan_status *wowlan_status = data->wowlan_status;
0010: 	u8 status_idx;
0011: 
0012: 	if (key->keyidx >= 0 && key->keyidx <= 3) {
0013: 		/* PTK */
0014: 		if (sta) {
0015: 			iwl_mld_update_ptk_rx_seq(data->mld, wowlan_status,
0016: 						  sta, key,
0017: 						  key->cipher ==
0018: 						  WLAN_CIPHER_SUITE_TKIP);
0019: 		/* GTK */
0020: 		} else {
0021: 			status_idx = key->keyidx == wowlan_status->gtk[1].id;
0022: 			iwl_mld_update_mcast_rx_seq(key,
0023: 						    &wowlan_status->gtk[status_idx]);
0024: 		}
0025: 	}
0026: 
0027: 	/* IGTK */
0028: 	if (key->keyidx == 4 || key->keyidx == 5) {
0029: 		if (key->keyidx == wowlan_status->igtk.id)
0030: 			iwl_mld_update_mcast_rx_seq(key, &wowlan_status->igtk);
0031: 	}
0032: 
0033: 	/* BIGTK */
0034: 	if (key->keyidx == 6 || key->keyidx == 7) {
0035: 		status_idx = key->keyidx == wowlan_status->bigtk[1].id;
0036: 		iwl_mld_update_mcast_rx_seq(key,
0037: 					    &wowlan_status->bigtk[status_idx]);
0038: 	}
0039: }

