0001: static int rx8025_get_time(struct device *dev, struct rtc_time *dt)
0002: {
0003: 	struct i2c_client *client = to_i2c_client(dev);
0004: 	struct rx8025_data *rx8025 = dev_get_drvdata(dev);
0005: 	u8 date[7];
0006: 	int err;
0007: 
0008: 	err = rx8025_check_validity(dev);
0009: 	if (err)
0010: 		return err;
0011: 
0012: 	err = rx8025_read_regs(client, RX8025_REG_SEC, 7, date);
0013: 	if (err)
0014: 		return err;
0015: 
0016: 	dev_dbg(dev, "%s: read %7ph\n", __func__, date);
0017: 
0018: 	dt->tm_sec = bcd2bin(date[RX8025_REG_SEC] & 0x7f);
0019: 	dt->tm_min = bcd2bin(date[RX8025_REG_MIN] & 0x7f);
0020: 	if (rx8025->is_24)
0021: 		dt->tm_hour = bcd2bin(date[RX8025_REG_HOUR] & 0x3f);
0022: 	else
0023: 		dt->tm_hour = bcd2bin(date[RX8025_REG_HOUR] & 0x1f) % 12
0024: 			+ (date[RX8025_REG_HOUR] & 0x20 ? 12 : 0);
0025: 
0026: 	dt->tm_mday = bcd2bin(date[RX8025_REG_MDAY] & 0x3f);
0027: 	dt->tm_mon = bcd2bin(date[RX8025_REG_MONTH] & 0x1f) - 1;
0028: 	dt->tm_year = bcd2bin(date[RX8025_REG_YEAR]) + 100;
0029: 
0030: 	dev_dbg(dev, "%s: date %ptRr\n", __func__, dt);
0031: 
0032: 	return 0;
0033: }

0001: static int rt298_set_bias_level(struct snd_soc_component *component,
0002: 				 enum snd_soc_bias_level level)
0003: {
0004: 	struct snd_soc_dapm_context *dapm = snd_soc_component_to_dapm(component);
0005: 
0006: 	switch (level) {
0007: 	case SND_SOC_BIAS_PREPARE:
0008: 		if (SND_SOC_BIAS_STANDBY == snd_soc_dapm_get_bias_level(dapm)) {
0009: 			snd_soc_component_write(component,
0010: 				RT298_SET_AUDIO_POWER, AC_PWRST_D0);
0011: 			snd_soc_component_update_bits(component, 0x0d, 0x200, 0x200);
0012: 			snd_soc_component_update_bits(component, 0x52, 0x80, 0x0);
0013: 			mdelay(20);
0014: 			snd_soc_component_update_bits(component, 0x0d, 0x200, 0x0);
0015: 			snd_soc_component_update_bits(component, 0x52, 0x80, 0x80);
0016: 		}
0017: 		break;
0018: 
0019: 	case SND_SOC_BIAS_STANDBY:
0020: 		snd_soc_component_write(component,
0021: 			RT298_SET_AUDIO_POWER, AC_PWRST_D3);
0022: 		break;
0023: 
0024: 	default:
0025: 		break;
0026: 	}
0027: 
0028: 	return 0;
0029: }

0001: int sctp_inet_listen(struct socket *sock, int backlog)
0002: {
0003: 	struct sock *sk = sock->sk;
0004: 	struct sctp_endpoint *ep = sctp_sk(sk)->ep;
0005: 	int err = -EINVAL;
0006: 
0007: 	if (unlikely(backlog < 0))
0008: 		return err;
0009: 
0010: 	lock_sock(sk);
0011: 
0012: 	/* Peeled-off sockets are not allowed to listen().  */
0013: 	if (sctp_style(sk, UDP_HIGH_BANDWIDTH))
0014: 		goto out;
0015: 
0016: 	if (sock->state != SS_UNCONNECTED)
0017: 		goto out;
0018: 
0019: 	if (!sctp_sstate(sk, LISTENING) && !sctp_sstate(sk, CLOSED))
0020: 		goto out;
0021: 
0022: 	/* If backlog is zero, disable listening. */
0023: 	if (!backlog) {
0024: 		if (sctp_sstate(sk, CLOSED))
0025: 			goto out;
0026: 
0027: 		err = 0;
0028: 		sctp_unhash_endpoint(ep);
0029: 		sk->sk_state = SCTP_SS_CLOSED;
0030: 		if (sk->sk_reuse || sctp_sk(sk)->reuse)
0031: 			sctp_sk(sk)->bind_hash->fastreuse = 1;
0032: 		goto out;
0033: 	}
0034: 
0035: 	/* If we are already listening, just update the backlog */
0036: 	if (sctp_sstate(sk, LISTENING))
0037: 		WRITE_ONCE(sk->sk_max_ack_backlog, backlog);
0038: 	else {
0039: 		err = sctp_listen_start(sk, backlog);
0040: 		if (err)
0041: 			goto out;
0042: 	}
0043: 
0044: 	err = 0;
0045: out:
0046: 	release_sock(sk);
0047: 	return err;
0048: }

0001: static void ci_otg_add_timer(struct ci_hdrc *ci, enum otg_fsm_timer t)
0002: {
0003: 	unsigned long flags, timer_sec, timer_nsec;
0004: 
0005: 	if (t >= NUM_OTG_FSM_TIMERS)
0006: 		return;
0007: 
0008: 	spin_lock_irqsave(&ci->lock, flags);
0009: 	timer_sec = otg_timer_ms[t] / MSEC_PER_SEC;
0010: 	timer_nsec = (otg_timer_ms[t] % MSEC_PER_SEC) * NSEC_PER_MSEC;
0011: 	ci->hr_timeouts[t] = ktime_add(ktime_get(),
0012: 				ktime_set(timer_sec, timer_nsec));
0013: 	ci->enabled_otg_timer_bits |= (1 << t);
0014: 	if ((ci->next_otg_timer == NUM_OTG_FSM_TIMERS) ||
0015: 			ktime_after(ci->hr_timeouts[ci->next_otg_timer],
0016: 						ci->hr_timeouts[t])) {
0017: 			ci->next_otg_timer = t;
0018: 			hrtimer_start_range_ns(&ci->otg_fsm_hrtimer,
0019: 					ci->hr_timeouts[t], NSEC_PER_MSEC,
0020: 							HRTIMER_MODE_ABS);
0021: 	}
0022: 	spin_unlock_irqrestore(&ci->lock, flags);
0023: }

0001: int qrtr_endpoint_register(struct qrtr_endpoint *ep, unsigned int nid)
0002: {
0003: 	struct qrtr_node *node;
0004: 
0005: 	if (!ep || !ep->xmit)
0006: 		return -EINVAL;
0007: 
0008: 	node = kzalloc_obj(*node);
0009: 	if (!node)
0010: 		return -ENOMEM;
0011: 
0012: 	kref_init(&node->ref);
0013: 	mutex_init(&node->ep_lock);
0014: 	skb_queue_head_init(&node->rx_queue);
0015: 	node->nid = QRTR_EP_NID_AUTO;
0016: 	node->ep = ep;
0017: 
0018: 	xa_init(&node->qrtr_tx_flow);
0019: 	mutex_init(&node->qrtr_tx_lock);
0020: 
0021: 	qrtr_node_assign(node, nid);
0022: 
0023: 	mutex_lock(&qrtr_node_lock);
0024: 	list_add(&node->item, &qrtr_all_nodes);
0025: 	mutex_unlock(&qrtr_node_lock);
0026: 	ep->node = node;
0027: 
0028: 	return 0;
0029: }

