0001: static int tsc2046_adc_scan(struct iio_dev *indio_dev)
0002: {
0003: 	struct tsc2046_adc_priv *priv = iio_priv(indio_dev);
0004: 	struct device *dev = &priv->spi->dev;
0005: 	int group;
0006: 	int ret;
0007: 
0008: 	ret = spi_sync(priv->spi, &priv->msg);
0009: 	if (ret < 0) {
0010: 		dev_err_ratelimited(dev, "SPI transfer failed: %pe\n", ERR_PTR(ret));
0011: 		return ret;
0012: 	}
0013: 
0014: 	for (group = 0; group < priv->groups; group++)
0015: 		priv->scan_buf.data[group] = tsc2046_adc_get_val(priv, group);
0016: 
0017: 	ret = iio_push_to_buffers_with_ts(indio_dev, &priv->scan_buf,
0018: 					  sizeof(priv->scan_buf),
0019: 					  iio_get_time_ns(indio_dev));
0020: 	/* If the consumer is kfifo, we may get a EBUSY here - ignore it. */
0021: 	if (ret < 0 && ret != -EBUSY) {
0022: 		dev_err_ratelimited(dev, "Failed to push scan buffer %pe\n",
0023: 				    ERR_PTR(ret));
0024: 
0025: 		return ret;
0026: 	}
0027: 
0028: 	return 0;
0029: }

0001: static struct vmw_user_surface *
0002: vmw_lookup_user_surface_for_buffer(struct vmw_private *vmw, struct vmw_bo *bo,
0003: 				   u32 handle)
0004: {
0005: 	struct vmw_user_surface *user_srf = NULL;
0006: 	struct vmw_surface *surf;
0007: 	struct ttm_base_object *base;
0008: 
0009: 	surf = vmw_bo_surface(bo);
0010: 	if (surf) {
0011: 		rcu_read_lock();
0012: 		user_srf = container_of(surf, struct vmw_user_surface, srf);
0013: 		base = &user_srf->prime.base;
0014: 		if (base && !kref_get_unless_zero(&base->refcount)) {
0015: 			drm_dbg_driver(&vmw->drm,
0016: 				       "%s: referencing a stale surface handle %d\n",
0017: 					__func__, handle);
0018: 			base = NULL;
0019: 			user_srf = NULL;
0020: 		}
