0001: static unsigned long dmz_shrink_mblock_cache(struct dmz_metadata *zmd,
0002: 					     unsigned long limit)
0003: {
0004: 	struct dmz_mblock *mblk;
0005: 	unsigned long count = 0;
0006: 
0007: 	if (!zmd->max_nr_mblks)
0008: 		return 0;
0009: 
0010: 	while (!list_empty(&zmd->mblk_lru_list) &&
0011: 	       atomic_read(&zmd->nr_mblks) > zmd->min_nr_mblks &&
0012: 	       count < limit) {
0013: 		mblk = list_first_entry(&zmd->mblk_lru_list,
0014: 					struct dmz_mblock, link);
0015: 		list_del_init(&mblk->link);
0016: 		rb_erase(&mblk->node, &zmd->mblk_rbtree);
0017: 		dmz_free_mblock(zmd, mblk);
0018: 		count++;
0019: 	}
0020: 
0021: 	return count;
0022: }

0001: static struct hsr_node *hsr_add_node(struct hsr_priv *hsr,
0002: 				     struct list_head *node_db,
0003: 				     unsigned char addr[], bool san,
0004: 				     enum hsr_port_type rx_port)
0005: {
0006: 	struct hsr_node *new_node, *node = NULL;
0007: 	unsigned long now;
0008: 	size_t block_sz;
0009: 	int i;
0010: 
0011: 	new_node = kzalloc_obj(*new_node, GFP_ATOMIC);
0012: 	if (!new_node)
0013: 		return NULL;
0014: 
0015: 	ether_addr_copy(new_node->macaddress_A, addr);
0016: 	spin_lock_init(&new_node->seq_out_lock);
0017: 
0018: 	if (hsr->prot_version == PRP_V1)
0019: 		new_node->seq_port_cnt = 1;
0020: 	else
0021: 		new_node->seq_port_cnt = HSR_PT_PORTS - 1;
0022: 
0023: 	block_sz = hsr_seq_block_size(new_node);
0024: 	new_node->block_buf = kcalloc(HSR_MAX_SEQ_BLOCKS, block_sz, GFP_ATOMIC);
0025: 	if (!new_node->block_buf)
0026: 		goto free;
0027: 
0028: 	xa_init(&new_node->seq_blocks);
0029: 
0030: 	/* We are only interested in time diffs here, so use current jiffies
0031: 	 * as initialization. (0 could trigger an spurious ring error warning).
0032: 	 */
0033: 	now = jiffies;
0034: 	for (i = 0; i < HSR_PT_PORTS; i++) {
0035: 		new_node->time_in[i] = now;
0036: 	}
0037: 
0038: 	if (san && hsr->proto_ops->handle_san_frame)
0039: 		hsr->proto_ops->handle_san_frame(san, rx_port, new_node);
0040: 
0041: 	spin_lock_bh(&hsr->list_lock);
0042: 	list_for_each_entry_rcu(node, node_db, mac_list,
0043: 				lockdep_is_held(&hsr->list_lock)) {
0044: 		if (ether_addr_equal(node->macaddress_A, addr))
0045: 			goto out;
0046: 		if (ether_addr_equal(node->macaddress_B, addr))
0047: 			goto out;
0048: 	}
0049: 	list_add_tail_rcu(&new_node->mac_list, node_db);
0050: 	spin_unlock_bh(&hsr->list_lock);
0051: 	return new_node;
0052: out:
0053: 	spin_unlock_bh(&hsr->list_lock);
0054: 	kfree(new_node->block_buf);
0055: free:
0056: 	kfree(new_node);
0057: 	return node;
0058: }

