0001: static int xr_tiocmget(struct tty_struct *tty)
0002: {
0003: 	struct usb_serial_port *port = tty->driver_data;
0004: 	struct xr_data *data = usb_get_serial_port_data(port);
0005: 	u16 status;
0006: 	int ret;
0007: 
0008: 	ret = xr_get_reg_uart(port, data->type->gpio_status, &status);
0009: 	if (ret)
0010: 		return ret;
0011: 
0012: 	/*
0013: 	 * Modem control pins are active low, so reading '0' means it is active
0014: 	 * and '1' means not active.
0015: 	 */
0016: 	ret = ((status & XR_GPIO_DTR) ? 0 : TIOCM_DTR) |
0017: 	      ((status & XR_GPIO_RTS) ? 0 : TIOCM_RTS) |
0018: 	      ((status & XR_GPIO_CTS) ? 0 : TIOCM_CTS) |
0019: 	      ((status & XR_GPIO_DSR) ? 0 : TIOCM_DSR) |
0020: 	      ((status & XR_GPIO_RI) ? 0 : TIOCM_RI) |
0021: 	      ((status & XR_GPIO_CD) ? 0 : TIOCM_CD);
0022: 
0023: 	return ret;
0024: }

