0001: static int  htmsetup_set(void *data, u64 val)
0002: {
0003: 	long rc, ret;
0004: 
0005: 	/*
0006: 	 * Input value: HTM buffer size in the power of 2
0007: 	 * example: hex value 0x21 ( decimal: 33 ) is for
0008: 	 * 8GB
0009: 	 * Invoke H_HTM call with:
0010: 	 * - operation as htm start (H_HTM_OP_SETUP)
0011: 	 * - parameter 1 set to input value.
0012: 	 * - last two values are unused, hence set to zero
0013: 	 */
0014: 	rc = htm_hcall_wrapper(htmflags, nodeindex, nodalchipindex, coreindexonchip,
0015: 			htmtype, H_HTM_OP_SETUP, val, 0, 0);
0016: 
0017: 	ret = htm_return_check(rc);
0018: 	if (ret <= 0) {
0019: 		pr_debug("H_HTM hcall failed for op: H_HTM_OP_SETUP, returning %ld\n", ret);
0020: 		return ret;
0021: 	}
0022: 
0023: 	/* Set htmsetup if H_HTM_OP_SETUP operation succeeds */
0024: 	htmsetup = val;
0025: 
0026: 	return 0;
0027: }

