0001: static void sof_hda_bus_link_power(struct hdac_device *codec, bool enable)
0002: {
0003: 	struct hdac_bus *bus = codec->bus;
0004: 	bool oldstate = test_bit(codec->addr, &bus->codec_powered);
0005: 
0006: 	snd_hdac_ext_bus_link_power(codec, enable);
0007: 
0008: 	if (enable == oldstate)
0009: 		return;
0010: 
0011: 	/*
0012: 	 * Both codec driver and controller can hold references to
0013: 	 * display power. To avoid unnecessary power-up/down cycles,
0014: 	 * controller doesn't immediately release its reference.
0015: 	 *
0016: 	 * If the codec driver powers down the link, release
0017: 	 * the controller reference as well.
0018: 	 */
0019: 	if (codec->addr == HDA_IDISP_ADDR && !enable)
0020: 		snd_hdac_display_power(bus, HDA_CODEC_IDX_CONTROLLER, false);
0021: 
0022: 	/* WAKEEN needs to be set for disabled links */
0023: 	update_codec_wake_enable(bus, codec->addr, enable);
0024: }

0001: static void xgbe_stop(struct xgbe_prv_data *pdata)
0002: {
0003: 	struct xgbe_hw_if *hw_if = &pdata->hw_if;
0004: 	struct xgbe_phy_if *phy_if = &pdata->phy_if;
0005: 	struct xgbe_channel *channel;
0006: 	struct net_device *netdev = pdata->netdev;
0007: 	struct netdev_queue *txq;
0008: 	unsigned int i;
0009: 
0010: 	DBGPR("-->xgbe_stop\n");
0011: 
0012: 	if (test_bit(XGBE_STOPPED, &pdata->dev_state))
0013: 		return;
0014: 
0015: 	netif_tx_stop_all_queues(netdev);
0016: 	netif_carrier_off(pdata->netdev);
0017: 
0018: 	xgbe_stop_timers(pdata);
0019: 	flush_workqueue(pdata->dev_workqueue);
0020: 
0021: 	xgbe_vxlan_unset_port(netdev, 0, 0, NULL);
0022: 
0023: 	hw_if->disable_tx(pdata);
0024: 	hw_if->disable_rx(pdata);
0025: 
0026: 	phy_if->phy_stop(pdata);
0027: 
0028: 	xgbe_free_irqs(pdata);
0029: 
0030: 	xgbe_napi_disable(pdata, 1);
0031: 
0032: 	hw_if->exit(pdata);
0033: 
0034: 	for (i = 0; i < pdata->channel_count; i++) {
0035: 		channel = pdata->channel[i];
0036: 		if (!channel->tx_ring)
0037: 			continue;
0038: 
0039: 		txq = netdev_get_tx_queue(netdev, channel->queue_index);
0040: 		netdev_tx_reset_queue(txq);
0041: 	}
0042: 
0043: 	set_bit(XGBE_STOPPED, &pdata->dev_state);
0044: 
0045: 	DBGPR("<--xgbe_stop\n");
0046: }

