0001: struct rds_message *rds_message_map_pages(unsigned long *page_addrs, unsigned int total_len)
0002: {
0003: 	struct rds_message *rm;
0004: 	unsigned int i;
0005: 	int num_sgs = DIV_ROUND_UP(total_len, PAGE_SIZE);
0006: 	int extra_bytes = num_sgs * sizeof(struct scatterlist);
0007: 
0008: 	rm = rds_message_alloc(extra_bytes, GFP_NOWAIT);
0009: 	if (!rm)
0010: 		return ERR_PTR(-ENOMEM);
0011: 
0012: 	set_bit(RDS_MSG_PAGEVEC, &rm->m_flags);
0013: 	rm->m_inc.i_hdr.h_len = cpu_to_be32(total_len);
0014: 	rm->data.op_nents = DIV_ROUND_UP(total_len, PAGE_SIZE);
0015: 	rm->data.op_sg = rds_message_alloc_sgs(rm, num_sgs);
0016: 	if (IS_ERR(rm->data.op_sg)) {
0017: 		void *err = ERR_CAST(rm->data.op_sg);
0018: 		rds_message_put(rm);
0019: 		return err;
0020: 	}
0021: 
0022: 	for (i = 0; i < rm->data.op_nents; ++i) {
0023: 		sg_set_page(&rm->data.op_sg[i],
0024: 				virt_to_page((void *)page_addrs[i]),
0025: 				PAGE_SIZE, 0);
0026: 	}
0027: 
0028: 	return rm;
0029: }

