0001: static int sh_msiof_dma_once(struct sh_msiof_spi_priv *p, const void *tx,
0002: 			     void *rx, unsigned int len,
0003: 			     unsigned int max_wdlen)
0004: {
0005: 	u32 ier_bits = 0;
0006: 	struct dma_async_tx_descriptor *desc_tx = NULL, *desc_rx = NULL;
0007: 	unsigned int words1, words2;
0008: 	dma_cookie_t cookie;
0009: 	int ret;
0010: 
0011: 	/* First prepare and submit the DMA request(s), as this may fail */
0012: 	if (rx) {
0013: 		ier_bits |= SIIER_RDREQE | SIIER_RDMAE;
0014: 		desc_rx = dmaengine_prep_slave_single(p->ctlr->dma_rx,
0015: 					p->rx_dma_addr, len, DMA_DEV_TO_MEM,
0016: 					DMA_PREP_INTERRUPT | DMA_CTRL_ACK);
0017: 		if (!desc_rx)
0018: 			return -EAGAIN;
0019: 
0020: 		desc_rx->callback = sh_msiof_dma_complete;
0021: 		desc_rx->callback_param = &p->done;
0022: 		cookie = dmaengine_submit(desc_rx);
0023: 		if (dma_submit_error(cookie))
0024: 			return cookie;
0025: 	}
0026: 
0027: 	if (tx) {
0028: 		ier_bits |= SIIER_TDREQE | SIIER_TDMAE;
0029: 		dma_sync_single_for_device(p->ctlr->dma_tx->device->dev,
0030: 					   p->tx_dma_addr, len, DMA_TO_DEVICE);
0031: 		desc_tx = dmaengine_prep_slave_single(p->ctlr->dma_tx,
0032: 					p->tx_dma_addr, len, DMA_MEM_TO_DEV,
0033: 					DMA_PREP_INTERRUPT | DMA_CTRL_ACK);
0034: 		if (!desc_tx) {
0035: 			ret = -EAGAIN;
0036: 			goto no_dma_tx;
0037: 		}
0038: 
0039: 		desc_tx->callback = sh_msiof_dma_complete;
0040: 		desc_tx->callback_param = &p->done_txdma;
0041: 		cookie = dmaengine_submit(desc_tx);
0042: 		if (dma_submit_error(cookie)) {
0043: 			ret = cookie;
0044: 			goto no_dma_tx;
0045: 		}
0046: 	}
0047: 
0048: 	/* 1 stage FIFO watermarks for DMA */
0049: 	sh_msiof_write(p, SIFCTR,
0050: 		       FIELD_PREP(SIFCTR_TFWM, SIFCTR_TFWM_1) |
0051: 		       FIELD_PREP(SIFCTR_RFWM, SIFCTR_RFWM_1));
0052: 
0053: 	/* setup msiof transfer mode registers (32-bit words) */
0054: 	words1 = min(len / 4, max_wdlen);
0055: 	words2 = len / 4 - words1;
0056: 	sh_msiof_spi_set_mode_regs(p, tx, rx, 32, words1, words2);
0057: 
0058: 	sh_msiof_write(p, SIIER, ier_bits);
0059: 
0060: 	reinit_completion(&p->done);
0061: 	if (tx)
0062: 		reinit_completion(&p->done_txdma);
0063: 	p->target_aborted = false;
0064: 
0065: 	/* Now start DMA */
0066: 	if (rx)
0067: 		dma_async_issue_pending(p->ctlr->dma_rx);
0068: 	if (tx)
0069: 		dma_async_issue_pending(p->ctlr->dma_tx);
0070: 
0071: 	ret = sh_msiof_spi_start(p, rx);
0072: 	if (ret) {
0073: 		dev_err(&p->pdev->dev, "failed to start hardware\n");
0074: 		goto stop_dma;
0075: 	}
0076: 
0077: 	if (tx) {
0078: 		/* wait for tx DMA completion */
0079: 		ret = sh_msiof_wait_for_completion(p, &p->done_txdma);
0080: 		if (ret)
0081: 			goto stop_reset;
0082: 	}
0083: 
0084: 	if (rx) {
0085: 		/* wait for rx DMA completion */
0086: 		ret = sh_msiof_wait_for_completion(p, &p->done);
0087: 		if (ret)
0088: 			goto stop_reset;
0089: 
0090: 		sh_msiof_write(p, SIIER, 0);
0091: 	} else {
0092: 		/* wait for tx fifo to be emptied */
0093: 		sh_msiof_write(p, SIIER, SIIER_TEOFE);
0094: 		ret = sh_msiof_wait_for_completion(p, &p->done);
0095: 		if (ret)
0096: 			goto stop_reset;
0097: 	}
0098: 
0099: 	/* clear status bits */
0100: 	sh_msiof_reset_str(p);
0101: 
0102: 	ret = sh_msiof_spi_stop(p, rx);
0103: 	if (ret) {
0104: 		dev_err(&p->pdev->dev, "failed to shut down hardware\n");
0105: 		return ret;
0106: 	}
0107: 
0108: 	if (rx)
0109: 		dma_sync_single_for_cpu(p->ctlr->dma_rx->device->dev,
0110: 					p->rx_dma_addr, len, DMA_FROM_DEVICE);
0111: 
0112: 	return 0;
0113: 
0114: stop_reset:
0115: 	sh_msiof_reset_str(p);
0116: 	sh_msiof_spi_stop(p, rx);
0117: stop_dma:
0118: 	if (tx)
0119: 		dmaengine_terminate_sync(p->ctlr->dma_tx);
0120: no_dma_tx:
0121: 	if (rx)
0122: 		dmaengine_terminate_sync(p->ctlr->dma_rx);
0123: 	sh_msiof_write(p, SIIER, 0);
0124: 	return ret;
0125: }

0001: void of_set_phy_timing_role(struct phy_device *phydev)
0002: {
0003: 	struct device_node *node = phydev->mdio.dev.of_node;
0004: 	const char *master;
0005: 
0006: 	if (!IS_ENABLED(CONFIG_OF_MDIO))
0007: 		return;
0008: 
0009: 	if (!node)
0010: 		return;
0011: 
0012: 	if (of_property_read_string(node, "timing-role", &master))
0013: 		return;
0014: 
0015: 	if (strcmp(master, "forced-master") == 0)
0016: 		phydev->master_slave_set = MASTER_SLAVE_CFG_MASTER_FORCE;
0017: 	else if (strcmp(master, "forced-slave") == 0)
0018: 		phydev->master_slave_set = MASTER_SLAVE_CFG_SLAVE_FORCE;
0019: 	else if (strcmp(master, "preferred-master") == 0)
0020: 		phydev->master_slave_set = MASTER_SLAVE_CFG_MASTER_PREFERRED;
0021: 	else if (strcmp(master, "preferred-slave") == 0)
0022: 		phydev->master_slave_set = MASTER_SLAVE_CFG_SLAVE_PREFERRED;
0023: 	else
0024: 		phydev_warn(phydev, "Unknown master-slave mode %s\n", master);
0025: }

0001: static int applespi_send_cmd_msg(struct applespi_data *applespi)
0002: {
0003: 	u16 crc;
0004: 	int sts;
0005: 	struct spi_packet *packet = (struct spi_packet *)applespi->tx_buffer;
0006: 	struct message *message = (struct message *)packet->data;
0007: 	u16 msg_len;
0008: 	u8 device;
0009: 
0010: 	/* check if draining */
0011: 	if (applespi->drain)
0012: 		return 0;
0013: 
0014: 	/* check whether send is in progress */
0015: 	if (applespi->cmd_msg_queued) {
0016: 		if (ktime_ms_delta(ktime_get(), applespi->cmd_msg_queued) < 1000)
0017: 			return 0;
0018: 
0019: 		dev_warn(&applespi->spi->dev, "Command %d timed out\n",
0020: 			 applespi->cmd_evt_type);
0021: 
0022: 		applespi->cmd_msg_queued = 0;
0023: 		applespi->write_active = false;
0024: 	}
0025: 
0026: 	/* set up packet */
0027: 	memset(packet, 0, APPLESPI_PACKET_SIZE);
0028: 
0029: 	/* are we processing init commands? */
0030: 	if (applespi->want_tp_info_cmd) {
0031: 		applespi->want_tp_info_cmd = false;
0032: 		applespi->want_mt_init_cmd = true;
0033: 		applespi->cmd_evt_type = ET_CMD_TP_INI;
0034: 
0035: 		/* build init command */
0036: 		device = PACKET_DEV_INFO;
0037: 
0038: 		message->type = cpu_to_le16(0x1020);
0039: 		msg_len = sizeof(message->tp_info_command);
0040: 
0041: 		message->zero = 0x02;
0042: 		message->rsp_buf_len = cpu_to_le16(0x0200);
0043: 
0044: 	} else if (applespi->want_mt_init_cmd) {
0045: 		applespi->want_mt_init_cmd = false;
0046: 		applespi->cmd_evt_type = ET_CMD_TP_INI;
0047: 
0048: 		/* build init command */
0049: 		device = PACKET_DEV_TPAD;
0050: 
0051: 		message->type = cpu_to_le16(0x0252);
0052: 		msg_len = sizeof(message->init_mt_command);
0053: 
0054: 		message->init_mt_command.cmd = cpu_to_le16(0x0102);
0055: 
0056: 	/* do we need caps-lock command? */
0057: 	} else if (applespi->want_cl_led_on != applespi->have_cl_led_on) {
0058: 		applespi->have_cl_led_on = applespi->want_cl_led_on;
0059: 		applespi->cmd_evt_type = ET_CMD_CL;
0060: 
0061: 		/* build led command */
0062: 		device = PACKET_DEV_KEYB;
0063: 
0064: 		message->type = cpu_to_le16(0x0151);
0065: 		msg_len = sizeof(message->capsl_command);
0066: 
0067: 		message->capsl_command.unknown = 0x01;
0068: 		message->capsl_command.led = applespi->have_cl_led_on ? 2 : 0;
0069: 
0070: 	/* do we need backlight command? */
0071: 	} else if (applespi->want_bl_level != applespi->have_bl_level) {
0072: 		applespi->have_bl_level = applespi->want_bl_level;
0073: 		applespi->cmd_evt_type = ET_CMD_BL;
0074: 
0075: 		/* build command buffer */
0076: 		device = PACKET_DEV_KEYB;
0077: 
0078: 		message->type = cpu_to_le16(0xB051);
0079: 		msg_len = sizeof(message->bl_command);
0080: 
0081: 		message->bl_command.const1 = cpu_to_le16(0x01B0);
0082: 		message->bl_command.level =
0083: 				cpu_to_le16(applespi->have_bl_level);
0084: 
0085: 		if (applespi->have_bl_level > 0)
0086: 			message->bl_command.const2 = cpu_to_le16(0x01F4);
0087: 		else
0088: 			message->bl_command.const2 = cpu_to_le16(0x0001);
0089: 
0090: 	/* everything's up-to-date */
0091: 	} else {
0092: 		return 0;
0093: 	}
0094: 
0095: 	/* finalize packet */
0096: 	packet->flags = PACKET_TYPE_WRITE;
0097: 	packet->device = device;
0098: 	packet->length = cpu_to_le16(MSG_HEADER_SIZE + msg_len);
0099: 
0100: 	message->counter = applespi->cmd_msg_cntr++ % (U8_MAX + 1);
0101: 
0102: 	message->length = cpu_to_le16(msg_len - 2);
0103: 	if (!message->rsp_buf_len)
0104: 		message->rsp_buf_len = message->length;
0105: 
0106: 	crc = crc16(0, (u8 *)message, le16_to_cpu(packet->length) - 2);
0107: 	put_unaligned_le16(crc, &message->data[msg_len - 2]);
0108: 
0109: 	crc = crc16(0, (u8 *)packet, sizeof(*packet) - 2);
0110: 	packet->crc16 = cpu_to_le16(crc);
0111: 
0112: 	/* send command */
0113: 	sts = applespi_async(applespi, &applespi->wr_m,
0114: 			     applespi_async_write_complete);
0115: 	if (sts) {
0116: 		dev_warn(&applespi->spi->dev,
0117: 			 "Error queueing async write to device: %d\n", sts);
0118: 		return sts;
0119: 	}
0120: 
0121: 	applespi->cmd_msg_queued = ktime_get_coarse();
0122: 	applespi->write_active = true;
0123: 
0124: 	return 0;
0125: }

