0001: void
0002: ath5k_hw_set_ledstate(struct ath5k_hw *ah, unsigned int state)
0003: {
0004: 	u32 led;
0005: 	/*5210 has different led mode handling*/
0006: 	u32 led_5210;
0007: 
0008: 	/*Reset led status*/
0009: 	if (ah->ah_version != AR5K_AR5210)
0010: 		AR5K_REG_DISABLE_BITS(ah, AR5K_PCICFG,
0011: 			AR5K_PCICFG_LEDMODE |  AR5K_PCICFG_LED);
0012: 	else
0013: 		AR5K_REG_DISABLE_BITS(ah, AR5K_PCICFG, AR5K_PCICFG_LED);
0014: 
0015: 	/*
0016: 	 * Some blinking values, define at your wish
0017: 	 */
0018: 	switch (state) {
0019: 	case AR5K_LED_SCAN:
0020: 	case AR5K_LED_AUTH:
0021: 		led = AR5K_PCICFG_LEDMODE_PROP | AR5K_PCICFG_LED_PEND;
0022: 		led_5210 = AR5K_PCICFG_LED_PEND | AR5K_PCICFG_LED_BCTL;
0023: 		break;
0024: 
0025: 	case AR5K_LED_INIT:
0026: 		led = AR5K_PCICFG_LEDMODE_PROP | AR5K_PCICFG_LED_NONE;
0027: 		led_5210 = AR5K_PCICFG_LED_PEND;
0028: 		break;
0029: 
0030: 	case AR5K_LED_ASSOC:
0031: 	case AR5K_LED_RUN:
0032: 		led = AR5K_PCICFG_LEDMODE_PROP | AR5K_PCICFG_LED_ASSOC;
0033: 		led_5210 = AR5K_PCICFG_LED_ASSOC;
0034: 		break;
0035: 
0036: 	default:
0037: 		led = AR5K_PCICFG_LEDMODE_PROM | AR5K_PCICFG_LED_NONE;
0038: 		led_5210 = AR5K_PCICFG_LED_PEND;
0039: 		break;
0040: 	}
0041: 
0042: 	/*Write new status to the register*/
0043: 	if (ah->ah_version != AR5K_AR5210)
0044: 		AR5K_REG_ENABLE_BITS(ah, AR5K_PCICFG, led);
0045: 	else
0046: 		AR5K_REG_ENABLE_BITS(ah, AR5K_PCICFG, led_5210);
0047: }

0001: static u32 qed_mcp_get_shmem_func(struct qed_hwfn *p_hwfn,
0002: 				  struct qed_ptt *p_ptt,
0003: 				  struct public_func *p_data, int pfid)
0004: {
0005: 	u32 addr = SECTION_OFFSIZE_ADDR(p_hwfn->mcp_info->public_base,
0006: 					PUBLIC_FUNC);
0007: 	u32 mfw_path_offsize = qed_rd(p_hwfn, p_ptt, addr);
0008: 	u32 func_addr;
0009: 	u32 i, size;
0010: 
0011: 	func_addr = SECTION_ADDR(mfw_path_offsize, pfid);
