0001: static int sync_regs(struct kvm_vcpu *vcpu)
0002: {
0003: 	if (vcpu->run->kvm_dirty_regs & KVM_SYNC_X86_REGS) {
0004: 		__set_regs(vcpu, &vcpu->run->s.regs.regs);
0005: 		vcpu->run->kvm_dirty_regs &= ~KVM_SYNC_X86_REGS;
0006: 	}
0007: 
0008: 	if (vcpu->run->kvm_dirty_regs & KVM_SYNC_X86_SREGS) {
0009: 		struct kvm_sregs sregs = vcpu->run->s.regs.sregs;
0010: 
0011: 		if (__set_sregs(vcpu, &sregs))
0012: 			return -EINVAL;
0013: 
0014: 		vcpu->run->kvm_dirty_regs &= ~KVM_SYNC_X86_SREGS;
0015: 	}
0016: 
0017: 	if (vcpu->run->kvm_dirty_regs & KVM_SYNC_X86_EVENTS) {
0018: 		struct kvm_vcpu_events events = vcpu->run->s.regs.events;
0019: 
0020: 		if (kvm_vcpu_ioctl_x86_set_vcpu_events(vcpu, &events))
0021: 			return -EINVAL;
0022: 
0023: 		vcpu->run->kvm_dirty_regs &= ~KVM_SYNC_X86_EVENTS;
0024: 	}
0025: 
0026: 	return 0;
0027: }

