0001: static int usba_ep_set_halt(struct usb_ep *_ep, int value)
0002: {
0003: 	struct usba_ep *ep = to_usba_ep(_ep);
0004: 	struct usba_udc *udc = ep->udc;
0005: 	unsigned long flags;
0006: 	int ret = 0;
0007: 
0008: 	DBG(DBG_GADGET, "endpoint %s: %s HALT\n", ep->ep.name,
0009: 			value ? "set" : "clear");
0010: 
0011: 	if (!ep->ep.desc) {
0012: 		DBG(DBG_ERR, "Attempted to halt uninitialized ep %s\n",
0013: 				ep->ep.name);
0014: 		return -ENODEV;
0015: 	}
0016: 	if (ep->is_isoc) {
0017: 		DBG(DBG_ERR, "Attempted to halt isochronous ep %s\n",
0018: 				ep->ep.name);
0019: 		return -ENOTTY;
0020: 	}
0021: 
0022: 	spin_lock_irqsave(&udc->lock, flags);
0023: 
0024: 	/*
0025: 	 * We can't halt IN endpoints while there are still data to be
0026: 	 * transferred
0027: 	 */
0028: 	if (!list_empty(&ep->queue)
0029: 			|| ((value && ep->is_in && (usba_ep_readl(ep, STA)
0030: 					& USBA_BF(BUSY_BANKS, -1L))))) {
0031: 		ret = -EAGAIN;
0032: 	} else {
0033: 		if (value)
0034: 			usba_ep_writel(ep, SET_STA, USBA_FORCE_STALL);
0035: 		else
0036: 			usba_ep_writel(ep, CLR_STA,
0037: 					USBA_FORCE_STALL | USBA_TOGGLE_CLR);
0038: 		usba_ep_readl(ep, STA);
0039: 	}
0040: 
0041: 	spin_unlock_irqrestore(&udc->lock, flags);
0042: 
0043: 	return ret;
0044: }

