0001: static void __mptcp_clean_una(struct sock *sk)
0002: {
0003: 	struct mptcp_sock *msk = mptcp_sk(sk);
0004: 	struct mptcp_data_frag *dtmp, *dfrag;
0005: 	u64 snd_una;
0006: 
0007: 	snd_una = msk->snd_una;
0008: 	list_for_each_entry_safe(dfrag, dtmp, &msk->rtx_queue, list) {
0009: 		if (after64(dfrag->data_seq + dfrag->data_len, snd_una))
0010: 			break;
0011: 
0012: 		if (unlikely(dfrag == msk->first_pending)) {
0013: 			/* in recovery mode can see ack after the current snd head */
0014: 			if (WARN_ON_ONCE(!msk->recovery))
0015: 				break;
0016: 
0017: 			msk->first_pending = mptcp_send_next(sk);
0018: 		}
0019: 
0020: 		dfrag_clear(sk, dfrag);
0021: 	}
0022: 
0023: 	dfrag = mptcp_rtx_head(sk);
0024: 	if (dfrag && after64(snd_una, dfrag->data_seq)) {
0025: 		u64 delta = snd_una - dfrag->data_seq;
0026: 
0027: 		/* prevent wrap around in recovery mode */
0028: 		if (unlikely(delta > dfrag->already_sent)) {
0029: 			if (WARN_ON_ONCE(!msk->recovery))
0030: 				goto out;
0031: 			if (WARN_ON_ONCE(delta > dfrag->data_len))
0032: 				goto out;
0033: 			dfrag->already_sent += delta - dfrag->already_sent;
0034: 		}
0035: 
0036: 		dfrag->data_seq += delta;
0037: 		dfrag->offset += delta;
0038: 		dfrag->data_len -= delta;
0039: 		dfrag->already_sent -= delta;
0040: 
0041: 		dfrag_uncharge(sk, delta);
0042: 	}
0043: 
0044: 	/* all retransmitted data acked, recovery completed */
0045: 	if (unlikely(msk->recovery) && after64(msk->snd_una, msk->recovery_snd_nxt))
0046: 		msk->recovery = false;
0047: 
0048: out:
0049: 	if (snd_una == msk->snd_nxt && snd_una == msk->write_seq) {
0050: 		if (mptcp_rtx_timer_pending(sk) && !mptcp_data_fin_enabled(msk))
0051: 			mptcp_stop_rtx_timer(sk);
0052: 	} else {
0053: 		mptcp_reset_rtx_timer(sk);
0054: 	}
0055: 
0056: 	if (mptcp_pending_data_fin_ack(sk))
0057: 		mptcp_schedule_work(sk);
0058: }

0001: static int psmouse_extensions(struct psmouse *psmouse,
0002: 			      unsigned int max_proto, bool set_properties)
0003: {
0004: 	bool synaptics_hardware = false;
0005: 	int ret;
0006: 
0007: 	/*
0008: 	 * Always check for focaltech, this is safe as it uses pnp-id
0009: 	 * matching.
0010: 	 */
0011: 	if (psmouse_do_detect(focaltech_detect,
0012: 			      psmouse, false, set_properties)) {
0013: 		if (max_proto > PSMOUSE_IMEX &&
0014: 		    IS_ENABLED(CONFIG_MOUSE_PS2_FOCALTECH) &&
0015: 		    (!set_properties || focaltech_init(psmouse) == 0)) {
0016: 			return PSMOUSE_FOCALTECH;
0017: 		}
0018: 		/*
0019: 		 * Restrict psmouse_max_proto so that psmouse_initialize()
0020: 		 * does not try to reset rate and resolution, because even
0021: 		 * that upsets the device.
0022: 		 * This also causes us to basically fall through to basic
0023: 		 * protocol detection, where we fully reset the mouse,
0024: 		 * and set it up as bare PS/2 protocol device.
0025: 		 */
0026: 		psmouse_max_proto = max_proto = PSMOUSE_PS2;
0027: 	}
0028: 
0029: 	/*
0030: 	 * We always check for LifeBook because it does not disturb mouse
0031: 	 * (it only checks DMI information).
0032: 	 */
0033: 	if (psmouse_try_protocol(psmouse, PSMOUSE_LIFEBOOK, &max_proto,
0034: 				 set_properties, max_proto > PSMOUSE_IMEX))
0035: 		return PSMOUSE_LIFEBOOK;
0036: 
0037: 	if (psmouse_try_protocol(psmouse, PSMOUSE_VMMOUSE, &max_proto,
0038: 				 set_properties, max_proto > PSMOUSE_IMEX))
0039: 		return PSMOUSE_VMMOUSE;
0040: 
0041: 	/*
0042: 	 * Try Kensington ThinkingMouse (we try first, because Synaptics
0043: 	 * probe upsets the ThinkingMouse).
0044: 	 */
0045: 	if (max_proto > PSMOUSE_IMEX &&
0046: 	    psmouse_try_protocol(psmouse, PSMOUSE_THINKPS, &max_proto,
0047: 				 set_properties, true)) {
0048: 		return PSMOUSE_THINKPS;
0049: 	}
0050: 
0051: 	/*
0052: 	 * Try Synaptics TouchPad. Note that probing is done even if
0053: 	 * Synaptics protocol support is disabled in config - we need to
0054: 	 * know if it is Synaptics so we can reset it properly after
0055: 	 * probing for IntelliMouse.
0056: 	 */
0057: 	if (max_proto > PSMOUSE_PS2 &&
0058: 	    psmouse_do_detect(synaptics_detect,
0059: 			      psmouse, false, set_properties)) {
0060: 		synaptics_hardware = true;
0061: 
0062: 		if (max_proto > PSMOUSE_IMEX) {
0063: 			/*
0064: 			 * Try activating protocol, but check if support is
0065: 			 * enabled first, since we try detecting Synaptics
0066: 			 * even when protocol is disabled.
0067: 			 */
0068: 			if (IS_ENABLED(CONFIG_MOUSE_PS2_SYNAPTICS) ||
0069: 			    IS_ENABLED(CONFIG_MOUSE_PS2_SYNAPTICS_SMBUS)) {
0070: 				if (!set_properties)
0071: 					return PSMOUSE_SYNAPTICS;
0072: 
0073: 				ret = synaptics_init(psmouse);
0074: 				if (ret >= 0)
0075: 					return ret;
0076: 			}
0077: 
0078: 			/*
0079: 			 * Some Synaptics touchpads can emulate extended
0080: 			 * protocols (like IMPS/2).  Unfortunately
0081: 			 * Logitech/Genius probes confuse some firmware
0082: 			 * versions so we'll have to skip them.
0083: 			 */
0084: 			max_proto = PSMOUSE_IMEX;
0085: 		}
0086: 
0087: 		/*
0088: 		 * Make sure that touchpad is in relative mode, gestures
0089: 		 * (taps) are enabled.
0090: 		 */
0091: 		synaptics_reset(psmouse);
0092: 	}
0093: 
0094: 	/*
0095: 	 * Try Cypress Trackpad. We must try it before Finger Sensing Pad
0096: 	 * because Finger Sensing Pad probe upsets some modules of Cypress
0097: 	 * Trackpads.
0098: 	 */
0099: 	if (max_proto > PSMOUSE_IMEX &&
0100: 	    psmouse_try_protocol(psmouse, PSMOUSE_CYPRESS, &max_proto,
0101: 				 set_properties, true)) {
0102: 		return PSMOUSE_CYPRESS;
0103: 	}
0104: 
0105: 	/* Try ALPS TouchPad */
0106: 	if (max_proto > PSMOUSE_IMEX) {
0107: 		ps2_command(&psmouse->ps2dev, NULL, PSMOUSE_CMD_RESET_DIS);
0108: 		if (psmouse_try_protocol(psmouse, PSMOUSE_ALPS,
0109: 					 &max_proto, set_properties, true))
0110: 			return PSMOUSE_ALPS;
0111: 	}
0112: 
0113: 	/* Try Elantech touchpad */
0114: 	if (max_proto > PSMOUSE_IMEX &&
0115: 	    psmouse_try_protocol(psmouse, PSMOUSE_ELANTECH,
0116: 				 &max_proto, set_properties, false)) {
0117: 		if (!set_properties)
0118: 			return PSMOUSE_ELANTECH;
0119: 
0120: 		ret = elantech_init(psmouse);
0121: 		if (ret >= 0)
0122: 			return ret;
0123: 	}
0124: 
0125: 	if (max_proto > PSMOUSE_IMEX) {
0126: 		if (psmouse_try_protocol(psmouse, PSMOUSE_GENPS,
0127: 					 &max_proto, set_properties, true))
0128: 			return PSMOUSE_GENPS;
0129: 
0130: 		if (psmouse_try_protocol(psmouse, PSMOUSE_PS2PP,
0131: 					 &max_proto, set_properties, true))
0132: 			return PSMOUSE_PS2PP;
0133: 
0134: 		if (psmouse_try_protocol(psmouse, PSMOUSE_TRACKPOINT,
0135: 					 &max_proto, set_properties, true))
0136: 			return PSMOUSE_TRACKPOINT;
0137: 
0138: 		if (psmouse_try_protocol(psmouse, PSMOUSE_TOUCHKIT_PS2,
0139: 					 &max_proto, set_properties, true))
0140: 			return PSMOUSE_TOUCHKIT_PS2;
0141: 	}
0142: 
0143: 	/*
0144: 	 * Try Finger Sensing Pad. We do it here because its probe upsets
0145: 	 * Trackpoint devices (causing TP_READ_ID command to time out).
0146: 	 */
0147: 	if (max_proto > PSMOUSE_IMEX &&
0148: 	    psmouse_try_protocol(psmouse, PSMOUSE_FSP,
0149: 				 &max_proto, set_properties, true)) {
0150: 		return PSMOUSE_FSP;
0151: 	}
0152: 
0153: 	/*
0154: 	 * Reset to defaults in case the device got confused by extended
0155: 	 * protocol probes. Note that we follow up with full reset because
0156: 	 * some mice put themselves to sleep when they see PSMOUSE_RESET_DIS.
0157: 	 */
0158: 	ps2_command(&psmouse->ps2dev, NULL, PSMOUSE_CMD_RESET_DIS);
0159: 	psmouse_reset(psmouse);
0160: 
0161: 	if (max_proto >= PSMOUSE_IMEX &&
0162: 	    psmouse_try_protocol(psmouse, PSMOUSE_IMEX,
0163: 				 &max_proto, set_properties, true)) {
0164: 		return PSMOUSE_IMEX;
0165: 	}
0166: 
0167: 	if (max_proto >= PSMOUSE_IMPS &&
0168: 	    psmouse_try_protocol(psmouse, PSMOUSE_IMPS,
0169: 				 &max_proto, set_properties, true)) {
0170: 		return PSMOUSE_IMPS;
0171: 	}
0172: 
0173: 	/*
0174: 	 * Okay, all failed, we have a standard mouse here. The number of
0175: 	 * the buttons is still a question, though. We assume 3.
0176: 	 */
0177: 	psmouse_try_protocol(psmouse, PSMOUSE_PS2,
0178: 			     &max_proto, set_properties, true);
0179: 
0180: 	if (synaptics_hardware) {
0181: 		/*
0182: 		 * We detected Synaptics hardware but it did not respond to
0183: 		 * IMPS/2 probes.  We need to reset the touchpad because if
0184: 		 * there is a track point on the pass through port it could
0185: 		 * get disabled while probing for protocol extensions.
0186: 		 */
0187: 		psmouse_reset(psmouse);
0188: 	}
0189: 
0190: 	return PSMOUSE_PS2;
0191: }

0001: static void dw_mipi_message_config(struct dw_mipi_dsi *dsi,
0002: 				   const struct mipi_dsi_msg *msg)
0003: {
0004: 	bool lpm = msg->flags & MIPI_DSI_MSG_USE_LPM;
0005: 	u32 val = 0;
0006: 
0007: 	/*
0008: 	 * TODO dw drv improvements
0009: 	 * largest packet sizes during hfp or during vsa/vpb/vfp
0010: 	 * should be computed according to byte lane, lane number and only
0011: 	 * if sending lp cmds in high speed is enable (PHY_TXREQUESTCLKHS)
0012: 	 */
0013: 	dsi_write(dsi, DSI_DPI_LP_CMD_TIM, OUTVACT_LPCMD_TIME(16)
0014: 		  | INVACT_LPCMD_TIME(4));
0015: 
0016: 	if (msg->flags & MIPI_DSI_MSG_REQ_ACK)
0017: 		val |= ACK_RQST_EN;
0018: 	if (lpm)
0019: 		val |= CMD_MODE_ALL_LP;
0020: 
0021: 	dsi_write(dsi, DSI_CMD_MODE_CFG, val);
0022: 
0023: 	val = dsi_read(dsi, DSI_VID_MODE_CFG);
0024: 	if (lpm)
0025: 		val |= ENABLE_LOW_POWER_CMD;
0026: 	else
0027: 		val &= ~ENABLE_LOW_POWER_CMD;
0028: 	dsi_write(dsi, DSI_VID_MODE_CFG, val);
0029: }

0001: void set_mcs_rate_by_mask(u8 *mcs_set, u32 mask)
0002: {
0003: 	u8 mcs_rate_1r = (u8)(mask & 0xff);
0004: 	u8 mcs_rate_2r = (u8)((mask >> 8) & 0xff);
0005: 	u8 mcs_rate_3r = (u8)((mask >> 16) & 0xff);
0006: 	u8 mcs_rate_4r = (u8)((mask >> 24) & 0xff);
0007: 
0008: 	mcs_set[0] &= mcs_rate_1r;
0009: 	mcs_set[1] &= mcs_rate_2r;
0010: 	mcs_set[2] &= mcs_rate_3r;
0011: 	mcs_set[3] &= mcs_rate_4r;
0012: }

