0001: u32 radeon_get_vblank_counter_kms(struct drm_crtc *crtc)
0002: {
0003: 	struct drm_device *dev = crtc->dev;
0004: 	unsigned int pipe = crtc->index;
0005: 	int vpos, hpos, stat;
0006: 	u32 count;
0007: 	struct radeon_device *rdev = dev->dev_private;
0008: 
0009: 	if (pipe >= rdev->num_crtc) {
0010: 		DRM_ERROR("Invalid crtc %u\n", pipe);
0011: 		return -EINVAL;
0012: 	}
0013: 
0014: 	/* The hw increments its frame counter at start of vsync, not at start
0015: 	 * of vblank, as is required by DRM core vblank counter handling.
0016: 	 * Cook the hw count here to make it appear to the caller as if it
0017: 	 * incremented at start of vblank. We measure distance to start of
0018: 	 * vblank in vpos. vpos therefore will be >= 0 between start of vblank
0019: 	 * and start of vsync, so vpos >= 0 means to bump the hw frame counter
0020: 	 * result by 1 to give the proper appearance to caller.
0021: 	 */
0022: 	if (rdev->mode_info.crtcs[pipe]) {
0023: 		/* Repeat readout if needed to provide stable result if
0024: 		 * we cross start of vsync during the queries.
0025: 		 */
0026: 		do {
0027: 			count = radeon_get_vblank_counter(rdev, pipe);
0028: 			/* Ask radeon_get_crtc_scanoutpos to return vpos as
0029: 			 * distance to start of vblank, instead of regular
0030: 			 * vertical scanout pos.
0031: 			 */
0032: 			stat = radeon_get_crtc_scanoutpos(
0033: 				dev, pipe, GET_DISTANCE_TO_VBLANKSTART,
0034: 				&vpos, &hpos, NULL, NULL,
0035: 				&rdev->mode_info.crtcs[pipe]->base.hwmode);
0036: 		} while (count != radeon_get_vblank_counter(rdev, pipe));
0037: 
0038: 		if (((stat & (DRM_SCANOUTPOS_VALID | DRM_SCANOUTPOS_ACCURATE)) !=
0039: 		    (DRM_SCANOUTPOS_VALID | DRM_SCANOUTPOS_ACCURATE))) {
0040: 			DRM_DEBUG_VBL("Query failed! stat %d\n", stat);
0041: 		}
0042: 		else {
0043: 			DRM_DEBUG_VBL("crtc %u: dist from vblank start %d\n",
0044: 				      pipe, vpos);
0045: 
0046: 			/* Bump counter if we are at >= leading edge of vblank,
0047: 			 * but before vsync where vpos would turn negative and
0048: 			 * the hw counter really increments.
0049: 			 */
0050: 			if (vpos >= 0)
0051: 				count++;
0052: 		}
0053: 	}
0054: 	else {
0055: 	    /* Fallback to use value as is. */
0056: 	    count = radeon_get_vblank_counter(rdev, pipe);
0057: 	    DRM_DEBUG_VBL("NULL mode info! Returned count may be wrong.\n");
0058: 	}
0059: 
0060: 	return count;
0061: }

0001: int
0002: snd_seq_oss_synth_sysex(struct seq_oss_devinfo *dp, int dev, unsigned char *buf, struct snd_seq_event *ev)
0003: {
0004: 	unsigned char *p;
0005: 	int len = 6;
0006: 
0007: 	p = memchr(buf, 0xff, 6);
0008: 	if (p)
0009: 		len = p - buf + 1;
0010: 
0011: 	/* copy the data to event record and send it */
0012: 	if (snd_seq_oss_synth_addr(dp, dev, ev))
0013: 		return -EINVAL;
0014: 	ev->flags = SNDRV_SEQ_EVENT_LENGTH_VARIABLE;
0015: 	ev->data.ext.len = len;
0016: 	ev->data.ext.ptr = buf;
0017: 	return 0;
0018: }

