0020: }

0001: static void rt2800_init_bbp_53xx(struct rt2x00_dev *rt2x00dev)
0002: {
0003: 	int ant, div_mode;
0004: 	u16 eeprom;
0005: 	u8 value;
0006: 
0007: 	rt2800_bbp4_mac_if_ctrl(rt2x00dev);
0008: 
0009: 	rt2800_bbp_write(rt2x00dev, 31, 0x08);
0010: 
0011: 	rt2800_bbp_write(rt2x00dev, 65, 0x2c);
0012: 	rt2800_bbp_write(rt2x00dev, 66, 0x38);
0013: 
0014: 	rt2800_bbp_write(rt2x00dev, 68, 0x0b);
0015: 
0016: 	rt2800_bbp_write(rt2x00dev, 69, 0x12);
0017: 	rt2800_bbp_write(rt2x00dev, 73, 0x13);
0018: 	rt2800_bbp_write(rt2x00dev, 75, 0x46);
0019: 	rt2800_bbp_write(rt2x00dev, 76, 0x28);
0020: 
0021: 	rt2800_bbp_write(rt2x00dev, 77, 0x59);
0022: 
0023: 	rt2800_bbp_write(rt2x00dev, 70, 0x0a);
0024: 
0025: 	rt2800_bbp_write(rt2x00dev, 79, 0x13);
0026: 	rt2800_bbp_write(rt2x00dev, 80, 0x05);
0027: 	rt2800_bbp_write(rt2x00dev, 81, 0x33);
0028: 
0029: 	rt2800_bbp_write(rt2x00dev, 82, 0x62);
0030: 
0031: 	rt2800_bbp_write(rt2x00dev, 83, 0x7a);
0032: 
0033: 	rt2800_bbp_write(rt2x00dev, 84, 0x9a);
0034: 
0035: 	rt2800_bbp_write(rt2x00dev, 86, 0x38);
0036: 
0037: 	if (rt2x00_rt(rt2x00dev, RT5392))
0038: 		rt2800_bbp_write(rt2x00dev, 88, 0x90);
0039: 
0040: 	rt2800_bbp_write(rt2x00dev, 91, 0x04);
0041: 
0042: 	rt2800_bbp_write(rt2x00dev, 92, 0x02);
0043: 
0044: 	if (rt2x00_rt(rt2x00dev, RT5392)) {
0045: 		rt2800_bbp_write(rt2x00dev, 95, 0x9a);
0046: 		rt2800_bbp_write(rt2x00dev, 98, 0x12);
0047: 	}
0048: 
0049: 	rt2800_bbp_write(rt2x00dev, 103, 0xc0);
0050: 
0051: 	rt2800_bbp_write(rt2x00dev, 104, 0x92);
0052: 
0053: 	rt2800_bbp_write(rt2x00dev, 105, 0x3c);
0054: 
0055: 	if (rt2x00_rt(rt2x00dev, RT5390))
0056: 		rt2800_bbp_write(rt2x00dev, 106, 0x03);
0057: 	else if (rt2x00_rt(rt2x00dev, RT5392))
0058: 		rt2800_bbp_write(rt2x00dev, 106, 0x12);
0059: 	else
0060: 		WARN_ON(1);
0061: 
0062: 	rt2800_bbp_write(rt2x00dev, 128, 0x12);
0063: 
0064: 	if (rt2x00_rt(rt2x00dev, RT5392)) {
0065: 		rt2800_bbp_write(rt2x00dev, 134, 0xd0);
0066: 		rt2800_bbp_write(rt2x00dev, 135, 0xf6);
0067: 	}
0068: 
0069: 	rt2800_disable_unused_dac_adc(rt2x00dev);
0070: 
0071: 	eeprom = rt2800_eeprom_read(rt2x00dev, EEPROM_NIC_CONF1);
0072: 	div_mode = rt2x00_get_field16(eeprom,
0073: 				      EEPROM_NIC_CONF1_ANT_DIVERSITY);
0074: 	ant = (div_mode == 3) ? 1 : 0;
0075: 
0076: 	/* check if this is a Bluetooth combo card */
0077: 	if (rt2x00_has_cap_bt_coexist(rt2x00dev)) {
0078: 		u32 reg;
0079: 
0080: 		reg = rt2800_register_read(rt2x00dev, GPIO_CTRL);
0081: 		rt2x00_set_field32(&reg, GPIO_CTRL_DIR3, 0);
0082: 		rt2x00_set_field32(&reg, GPIO_CTRL_DIR6, 0);
0083: 		rt2x00_set_field32(&reg, GPIO_CTRL_VAL3, 0);
0084: 		rt2x00_set_field32(&reg, GPIO_CTRL_VAL6, 0);
0085: 		if (ant == 0)
0086: 			rt2x00_set_field32(&reg, GPIO_CTRL_VAL3, 1);
0087: 		else if (ant == 1)
0088: 			rt2x00_set_field32(&reg, GPIO_CTRL_VAL6, 1);
0089: 		rt2800_register_write(rt2x00dev, GPIO_CTRL, reg);
0090: 	}
0091: 
0092: 	/* These chips have hardware RX antenna diversity */
0093: 	if (rt2x00_rt_rev_gte(rt2x00dev, RT5390, REV_RT5390R) ||
0094: 	    rt2x00_rt_rev_gte(rt2x00dev, RT5390, REV_RT5370G)) {
0095: 		rt2800_bbp_write(rt2x00dev, 150, 0); /* Disable Antenna Software OFDM */
0096: 		rt2800_bbp_write(rt2x00dev, 151, 0); /* Disable Antenna Software CCK */
0097: 		rt2800_bbp_write(rt2x00dev, 154, 0); /* Clear previously selected antenna */
0098: 	}
0099: 
0100: 	value = rt2800_bbp_read(rt2x00dev, 152);
0101: 	if (ant == 0)
0102: 		rt2x00_set_field8(&value, BBP152_RX_DEFAULT_ANT, 1);
0103: 	else
0104: 		rt2x00_set_field8(&value, BBP152_RX_DEFAULT_ANT, 0);
0105: 	rt2800_bbp_write(rt2x00dev, 152, value);
0106: 
0107: 	rt2800_init_freq_calibration(rt2x00dev);
0108: }

