0001: static bool hub_descriptor_is_sane(struct usb_host_interface *desc)
0002: {
0003: 	/* Some hubs have a subclass of 1, which AFAICT according to the */
0004: 	/*  specs is not defined, but it works */
0005: 	if (desc->desc.bInterfaceSubClass != 0 &&
0006: 	    desc->desc.bInterfaceSubClass != 1)
0007: 		return false;
0008: 
0009: 	/* Multiple endpoints? What kind of mutant ninja-hub is this? */
0010: 	if (desc->desc.bNumEndpoints != 1)
0011: 		return false;
0012: 
0013: 	/* If the first endpoint is not interrupt IN, we'd better punt! */
0014: 	if (!usb_endpoint_is_int_in(&desc->endpoint[0].desc))
0015: 		return false;
0016: 
0017:         return true;
0018: }

