0001: static long queue_stack_map_push_elem(struct bpf_map *map, void *value,
0002: 				      u64 flags)
0003: {
0004: 	struct bpf_queue_stack *qs = bpf_queue_stack(map);
0005: 	unsigned long irq_flags;
0006: 	int err = 0;
0007: 	void *dst;
0008: 
0009: 	/* BPF_EXIST is used to force making room for a new element in case the
0010: 	 * map is full
0011: 	 */
0012: 	bool replace = (flags & BPF_EXIST);
0013: 
0014: 	/* Check supported flags for queue and stack maps */
0015: 	if (flags & BPF_NOEXIST || flags > BPF_EXIST)
0016: 		return -EINVAL;
0017: 
0018: 	if (raw_res_spin_lock_irqsave(&qs->lock, irq_flags))
0019: 		return -EBUSY;
0020: 
0021: 	if (queue_stack_map_is_full(qs)) {
0022: 		if (!replace) {
0023: 			err = -E2BIG;
0024: 			goto out;
0025: 		}
0026: 		/* advance tail pointer to overwrite oldest element */
0027: 		if (unlikely(++qs->tail >= qs->size))
0028: 			qs->tail = 0;
0029: 	}
0030: 
0031: 	dst = &qs->elements[qs->head * qs->map.value_size];
0032: 	memcpy(dst, value, qs->map.value_size);
0033: 
0034: 	if (unlikely(++qs->head >= qs->size))
0035: 		qs->head = 0;
0036: 
0037: out:
0038: 	raw_res_spin_unlock_irqrestore(&qs->lock, irq_flags);
0039: 	return err;
0040: }

