0001: static void smk_net4addr_insert(struct smk_net4addr *new)
0002: {
0003: 	struct smk_net4addr *m;
0004: 	struct smk_net4addr *m_next;
0005: 
0006: 	if (list_empty(&smk_net4addr_list)) {
0007: 		list_add_rcu(&new->list, &smk_net4addr_list);
0008: 		return;
0009: 	}
0010: 
0011: 	m = list_entry_rcu(smk_net4addr_list.next,
0012: 			   struct smk_net4addr, list);
0013: 
0014: 	/* the comparison '>' is a bit hacky, but works */
0015: 	if (new->smk_masks > m->smk_masks) {
0016: 		list_add_rcu(&new->list, &smk_net4addr_list);
0017: 		return;
0018: 	}
0019: 
0020: 	list_for_each_entry_rcu(m, &smk_net4addr_list, list) {
0021: 		if (list_is_last(&m->list, &smk_net4addr_list)) {
0022: 			list_add_rcu(&new->list, &m->list);
0023: 			return;
0024: 		}
0025: 		m_next = list_entry_rcu(m->list.next,
0026: 					struct smk_net4addr, list);
0027: 		if (new->smk_masks > m_next->smk_masks) {
0028: 			list_add_rcu(&new->list, &m->list);
0029: 			return;
0030: 		}
0031: 	}
0032: }

0001: static void wm8904_set_retune_mobile(struct snd_soc_component *component)
0002: {
0003: 	struct wm8904_priv *wm8904 = snd_soc_component_get_drvdata(component);
0004: 	struct wm8904_pdata *pdata = wm8904->pdata;
0005: 	int best, best_val, save, i, cfg;
0006: 
0007: 	if (!pdata || !wm8904->num_retune_mobile_texts)
0008: 		return;
0009: 
0010: 	/* Find the version of the currently selected configuration
0011: 	 * with the nearest sample rate. */
0012: 	cfg = wm8904->retune_mobile_cfg;
0013: 	best = 0;
0014: 	best_val = INT_MAX;
0015: 	for (i = 0; i < pdata->num_retune_mobile_cfgs; i++) {
0016: 		if (strcmp(pdata->retune_mobile_cfgs[i].name,
0017: 			   wm8904->retune_mobile_texts[cfg]) == 0 &&
0018: 		    abs(pdata->retune_mobile_cfgs[i].rate
0019: 			- wm8904->fs) < best_val) {
0020: 			best = i;
0021: 			best_val = abs(pdata->retune_mobile_cfgs[i].rate
0022: 				       - wm8904->fs);
0023: 		}
0024: 	}
0025: 
0026: 	dev_dbg(component->dev, "ReTune Mobile %s/%dHz for %dHz sample rate\n",
0027: 		pdata->retune_mobile_cfgs[best].name,
0028: 		pdata->retune_mobile_cfgs[best].rate,
0029: 		wm8904->fs);
0030: 
0031: 	/* The EQ will be disabled while reconfiguring it, remember the
0032: 	 * current configuration. 
0033: 	 */
0034: 	save = snd_soc_component_read(component, WM8904_EQ1);
0035: 
0036: 	for (i = 0; i < WM8904_EQ_REGS; i++)
0037: 		snd_soc_component_update_bits(component, WM8904_EQ1 + i, 0xffff,
0038: 				pdata->retune_mobile_cfgs[best].regs[i]);
0039: 
0040: 	snd_soc_component_update_bits(component, WM8904_EQ1, WM8904_EQ_ENA, save);
0041: }

0001: static int virtnet_xsk_pool_enable(struct net_device *dev,
0002: 				   struct xsk_buff_pool *pool,
0003: 				   u16 qid)
0004: {
0005: 	struct virtnet_info *vi = netdev_priv(dev);
0006: 	struct receive_queue *rq;
0007: 	struct device *dma_dev;
0008: 	struct send_queue *sq;
0009: 	dma_addr_t hdr_dma;
0010: 	int err, size;
0011: 
0012: 	if (vi->hdr_len > xsk_pool_get_headroom(pool))
0013: 		return -EINVAL;
0014: 
0015: 	/* In big_packets mode, xdp cannot work, so there is no need to
0016: 	 * initialize xsk of rq.
0017: 	 */
0018: 	if (!vi->rq[qid].page_pool)
0019: 		return -ENOENT;
0020: 
0021: 	if (qid >= vi->curr_queue_pairs)
0022: 		return -EINVAL;
0023: 
0024: 	sq = &vi->sq[qid];
0025: 	rq = &vi->rq[qid];
0026: 
0027: 	/* xsk assumes that tx and rx must have the same dma device. The af-xdp
0028: 	 * may use one buffer to receive from the rx and reuse this buffer to
0029: 	 * send by the tx. So the dma dev of sq and rq must be the same one.
0030: 	 *
0031: 	 * But vq->dma_dev allows every vq has the respective dma dev. So I
0032: 	 * check the dma dev of vq and sq is the same dev.
0033: 	 */
0034: 	if (virtqueue_dma_dev(rq->vq) != virtqueue_dma_dev(sq->vq))
0035: 		return -EINVAL;
0036: 
0037: 	dma_dev = virtqueue_dma_dev(rq->vq);
0038: 	if (!dma_dev)
0039: 		return -EINVAL;
0040: 
0041: 	size = virtqueue_get_vring_size(rq->vq);
0042: 
0043: 	rq->xsk_buffs = kvzalloc_objs(*rq->xsk_buffs, size);
0044: 	if (!rq->xsk_buffs)
0045: 		return -ENOMEM;
0046: 
0047: 	hdr_dma = virtqueue_map_single_attrs(sq->vq, &xsk_hdr, vi->hdr_len,
0048: 					     DMA_TO_DEVICE, 0);
0049: 	if (virtqueue_map_mapping_error(sq->vq, hdr_dma)) {
0050: 		err = -ENOMEM;
0051: 		goto err_free_buffs;
0052: 	}
0053: 
0054: 	err = xsk_pool_dma_map(pool, dma_dev, 0);
0055: 	if (err)
0056: 		goto err_xsk_map;
0057: 
0058: 	err = virtnet_rq_bind_xsk_pool(vi, rq, pool);
0059: 	if (err)
0060: 		goto err_rq;
0061: 
0062: 	err = virtnet_sq_bind_xsk_pool(vi, sq, pool);
0063: 	if (err)
0064: 		goto err_sq;
0065: 
0066: 	/* Now, we do not support tx offload(such as tx csum), so all the tx
0067: 	 * virtnet hdr is zero. So all the tx packets can share a single hdr.
0068: 	 */
0069: 	sq->xsk_hdr_dma_addr = hdr_dma;
0070: 
0071: 	return 0;
0072: 
0073: err_sq:
0074: 	virtnet_rq_bind_xsk_pool(vi, rq, NULL);
0075: err_rq:
0076: 	xsk_pool_dma_unmap(pool, 0);
0077: err_xsk_map:
0078: 	virtqueue_unmap_single_attrs(rq->vq, hdr_dma, vi->hdr_len,
0079: 				     DMA_TO_DEVICE, 0);
0080: err_free_buffs:
0081: 	kvfree(rq->xsk_buffs);
0082: 	return err;
0083: }

0001: static void cxgbit_free_skb(struct cxgbit_sock *csk)
0002: {
0003: 	struct sk_buff *skb;
0004: 
0005: 	__skb_queue_purge(&csk->txq);
0006: 	__skb_queue_purge(&csk->rxq);
0007: 	__skb_queue_purge(&csk->backlogq);
0008: 	__skb_queue_purge(&csk->ppodq);
0009: 	__skb_queue_purge(&csk->skbq);
0010: 
0011: 	while ((skb = cxgbit_sock_dequeue_wr(csk)))
0012: 		kfree_skb(skb);
0013: 
0014: 	__kfree_skb(csk->lro_hskb);
0015: }

