0001: static int kvmhv_vcpu_entry_p9_nested(struct kvm_vcpu *vcpu, u64 time_limit, unsigned long lpcr, u64 *tb)
0002: {
0003: 	unsigned long host_psscr;
0004: 	unsigned long msr;
0005: 	struct hv_guest_state hvregs;
0006: 	struct p9_host_os_sprs host_os_sprs;
0007: 	s64 dec;
0008: 	int trap;
0009: 
0010: 	msr = mfmsr();
0011: 
0012: 	save_p9_host_os_sprs(&host_os_sprs);
0013: 
0014: 	/*
0015: 	 * We need to save and restore the guest visible part of the
0016: 	 * psscr (i.e. using SPRN_PSSCR_PR) since the hypervisor
0017: 	 * doesn't do this for us. Note only required if pseries since
0018: 	 * this is done in kvmhv_vcpu_entry_p9() below otherwise.
0019: 	 */
0020: 	host_psscr = mfspr(SPRN_PSSCR_PR);
0021: 
0022: 	kvmppc_msr_hard_disable_set_facilities(vcpu, msr);
0023: 	if (lazy_irq_pending())
0024: 		return 0;
0025: 
0026: 	if (unlikely(load_vcpu_state(vcpu, &host_os_sprs)))
0027: 		msr = mfmsr(); /* TM restore can update msr */
0028: 
0029: 	if (vcpu->arch.psscr != host_psscr)
0030: 		mtspr(SPRN_PSSCR_PR, vcpu->arch.psscr);
0031: 
0032: 	kvmhv_save_hv_regs(vcpu, &hvregs);
0033: 	hvregs.lpcr = lpcr;
0034: 	hvregs.amor = ~0;
0035: 	vcpu->arch.regs.msr = vcpu->arch.shregs.msr;
0036: 	hvregs.version = HV_GUEST_STATE_VERSION;
0037: 	if (vcpu->arch.nested) {
0038: 		hvregs.lpid = vcpu->arch.nested->shadow_lpid;
0039: 		hvregs.vcpu_token = vcpu->arch.nested_vcpu_id;
0040: 	} else {
0041: 		hvregs.lpid = vcpu->kvm->arch.lpid;
0042: 		hvregs.vcpu_token = vcpu->vcpu_id;
0043: 	}
0044: 	hvregs.hdec_expiry = time_limit;
0045: 
0046: 	/*
0047: 	 * hvregs has the doorbell status, so zero it here which
0048: 	 * enables us to receive doorbells when H_ENTER_NESTED is
0049: 	 * in progress for this vCPU
0050: 	 */
0051: 
0052: 	if (vcpu->arch.doorbell_request)
0053: 		vcpu->arch.doorbell_request = 0;
0054: 
0055: 	/*
0056: 	 * When setting DEC, we must always deal with irq_work_raise
0057: 	 * via NMI vs setting DEC. The problem occurs right as we
0058: 	 * switch into guest mode if a NMI hits and sets pending work
0059: 	 * and sets DEC, then that will apply to the guest and not
0060: 	 * bring us back to the host.
0061: 	 *
0062: 	 * irq_work_raise could check a flag (or possibly LPCR[HDICE]
0063: 	 * for example) and set HDEC to 1? That wouldn't solve the
0064: 	 * nested hv case which needs to abort the hcall or zero the
0065: 	 * time limit.
0066: 	 *
0067: 	 * XXX: Another day's problem.
0068: 	 */
0069: 	mtspr(SPRN_DEC, kvmppc_dec_expires_host_tb(vcpu) - *tb);
0070: 
0071: 	mtspr(SPRN_DAR, vcpu->arch.shregs.dar);
0072: 	mtspr(SPRN_DSISR, vcpu->arch.shregs.dsisr);
0073: 	switch_pmu_to_guest(vcpu, &host_os_sprs);
0074: 	accumulate_time(vcpu, &vcpu->arch.in_guest);
0075: 	trap = plpar_hcall_norets(H_ENTER_NESTED, __pa(&hvregs),
0076: 				  __pa(&vcpu->arch.regs));
0077: 	accumulate_time(vcpu, &vcpu->arch.guest_exit);
0078: 	kvmhv_restore_hv_return_state(vcpu, &hvregs);
0079: 	switch_pmu_to_host(vcpu, &host_os_sprs);
0080: 	vcpu->arch.shregs.msr = vcpu->arch.regs.msr;
0081: 	vcpu->arch.shregs.dar = mfspr(SPRN_DAR);
0082: 	vcpu->arch.shregs.dsisr = mfspr(SPRN_DSISR);
0083: 	vcpu->arch.psscr = mfspr(SPRN_PSSCR_PR);
0084: 
0085: 	store_vcpu_state(vcpu);
0086: 
0087: 	dec = mfspr(SPRN_DEC);
0088: 	if (!(lpcr & LPCR_LD)) /* Sign extend if not using large decrementer */
0089: 		dec = (s32) dec;
0090: 	*tb = mftb();
0091: 	vcpu->arch.dec_expires = dec + (*tb + kvmppc_get_tb_offset(vcpu));
0092: 
0093: 	timer_rearm_host_dec(*tb);
0094: 
0095: 	restore_p9_host_os_sprs(vcpu, &host_os_sprs);
0096: 	if (vcpu->arch.psscr != host_psscr)
0097: 		mtspr(SPRN_PSSCR_PR, host_psscr);
0098: 
0099: 	return trap;
0100: }

0001: static int inno_hdmi_find_phy_config(struct inno_hdmi *hdmi,
