0001: static void sun8i_ce_cipher_unprepare(struct skcipher_request *areq,
0002: 				      struct ce_task *cet)
0003: {
0004: 	struct crypto_skcipher *tfm = crypto_skcipher_reqtfm(areq);
0005: 	struct sun8i_cipher_tfm_ctx *op = crypto_skcipher_ctx(tfm);
0006: 	struct sun8i_ce_dev *ce = op->ce;
0007: 	struct sun8i_cipher_req_ctx *rctx = skcipher_request_ctx(areq);
0008: 	unsigned int ivsize, offset;
0009: 	int nr_sgs = rctx->nr_sgs;
0010: 	int nr_sgd = rctx->nr_sgd;
0011: 
0012: 	ivsize = crypto_skcipher_ivsize(tfm);
0013: 
0014: 	if (areq->src == areq->dst) {
0015: 		dma_unmap_sg(ce->dev, areq->src, nr_sgs, DMA_BIDIRECTIONAL);
0016: 	} else {
0017: 		if (nr_sgs > 0)
0018: 			dma_unmap_sg(ce->dev, areq->src, nr_sgs, DMA_TO_DEVICE);
0019: 		dma_unmap_sg(ce->dev, areq->dst, nr_sgd, DMA_FROM_DEVICE);
0020: 	}
0021: 
0022: 	if (areq->iv && ivsize > 0) {
0023: 		if (cet->t_iv)
0024: 			dma_unmap_single(ce->dev, rctx->addr_iv, ivsize,
0025: 					 DMA_TO_DEVICE);
0026: 		offset = areq->cryptlen - ivsize;
0027: 		if (rctx->op_dir & CE_DECRYPTION) {
0028: 			memcpy(areq->iv, rctx->backup_iv, ivsize);
0029: 			memzero_explicit(rctx->backup_iv, ivsize);
0030: 		} else {
0031: 			scatterwalk_map_and_copy(areq->iv, areq->dst, offset,
0032: 						 ivsize, 0);
0033: 		}
0034: 		memzero_explicit(rctx->bounce_iv, ivsize);
0035: 	}
0036: 
0037: 	dma_unmap_single(ce->dev, rctx->addr_key, op->keylen, DMA_TO_DEVICE);
0038: }
